"""Vectors generated by running the original des.js through node."""

import unittest

from sdu_connect.des import str_enc


VECTORS = [
    ("1", "FF175F03E46ADFCE"),
    ("1234", "C1BB5938DF9F2190"),
    ("admin", "012C2C9BA925FAF8045B2FD9B02A2664"),
    (
        "202100001",
        "B6FC8B80C5445D4B315CB4B8654EACF2FF175F03E46ADFCE",
    ),
    ("aB3!x", "18ED6B4F960543424B4072F73C901FDD"),
    ("测试", "ECDF711BBA3BBCDB"),
    (
        "1234567890abcdef",
        "C1BB5938DF9F2190B89172CB54C8C33ABEB58204744CA7CF2161BB34952010E8",
    ),
]


class StrEncTest(unittest.TestCase):
    def test_known_vectors(self) -> None:
        for plain, expected in VECTORS:
            with self.subTest(plain=plain):
                self.assertEqual(str_enc(plain), expected)

    def test_empty(self) -> None:
        self.assertEqual(str_enc(""), "")


if __name__ == "__main__":
    unittest.main()
